settings.css:
.dg-chat{
  --ink:#0F172A;--muted:#64748B;--line:#E2E8F0;--panel:#F8FAFC;--accent:#0F766E;--user:#1D4ED8;
  position:absolute;inset:0;display:flex;flex-direction:column;gap:10px;padding:10px 12px 12px;
  box-sizing:border-box;color:var(--ink);font-family:Roboto,"Segoe UI",Helvetica,Arial,sans-serif;
  overflow:hidden;background:#fff;
}
.dg-chat__thread{flex:1 1 auto;min-height:0;overflow:auto;display:flex;flex-direction:column;gap:10px;padding:12px;border:1px solid var(--line);border-radius:14px;background:linear-gradient(180deg,#fff 0%,#F8FAFC 100%);scroll-behavior:smooth}
.dg-chat__empty{margin:auto;text-align:left;max-width:28rem;color:var(--muted);padding:12px 8px}
.dg-chat__empty-title{font-size:15px;font-weight:600;color:var(--ink);margin-bottom:8px}
.dg-chat__empty-text{font-size:13px;line-height:1.5;margin-bottom:10px}
.dg-chat__device-list{margin:0;padding-left:1.2rem;color:var(--ink);font-size:13px;line-height:1.7}
.dg-chat__device-list li{margin:2px 0}
.dg-chat__selected{flex:0 0 auto;font-size:12px;color:var(--muted);padding:0 2px}
.dg-chat__selected strong{color:var(--accent);font-weight:700}
.dg-chat__row{display:flex;gap:8px;align-items:flex-end;max-width:94%;animation:dgRise .22s ease both}
.dg-chat__row--user{align-self:flex-end;flex-direction:row-reverse}
.dg-chat__row--assistant{align-self:flex-start}
.dg-chat__avatar{flex:0 0 26px;width:26px;height:26px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:800}
.dg-chat__row--assistant .dg-chat__avatar{background:#ECFDF5;color:var(--accent);border:1px solid #99F6E4}
.dg-chat__row--user .dg-chat__avatar{background:#DBEAFE;color:var(--user);border:1px solid #93C5FD}
.dg-chat__bubble{padding:10px 12px;border-radius:14px;font-size:13px;line-height:1.5;white-space:pre-wrap;word-break:break-word}
.dg-chat__row--assistant .dg-chat__bubble{background:#fff;border:1px solid var(--line);border-bottom-left-radius:5px}
.dg-chat__row--user .dg-chat__bubble{background:var(--user);color:#fff;border-bottom-right-radius:5px}
.dg-chat__meta{margin-top:5px;font-size:10px;opacity:.7}
.dg-chat__bottom{flex:0 0 auto;display:flex;flex-direction:column;gap:8px}
.dg-chat__composer{display:flex;gap:8px;align-items:stretch}
.dg-chat__composer textarea{flex:1;resize:none;height:56px;min-height:56px;max-height:56px;padding:10px 12px;border:1px solid var(--line);border-radius:12px;font-size:13px;line-height:1.4;outline:none;box-sizing:border-box;background:#fff}
.dg-chat__composer textarea:focus{border-color:#0F766E;box-shadow:0 0 0 3px rgba(15,118,110,.12)}
.dg-chat__send{min-width:88px;border:none;border-radius:12px;background:linear-gradient(180deg,#0F766E 0%,#0D9488 100%);color:#fff;font-size:13px;font-weight:700;cursor:pointer}
.dg-chat__send:disabled{opacity:.55;cursor:not-allowed}
@keyframes dgRise{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:none}}

settings.js:
const cfg = {
  copilotBaseUrl: (window.TB_COPILOT_BASE_URL || (window.location.origin + '/copilot')),
  storageKey: 'tb-operator-copilot-v2'
};

const root = container.querySelector('.dg-chat');
const messagesEl = root.querySelector('#dg-chat-messages');
const inputEl = root.querySelector('#dg-chat-input');
const sendEl = root.querySelector('#dg-chat-send');

let devices = [];
let state = {
  busy: false,
  conversationId: null,
  selectedDeviceId: null,
  selectedDeviceName: null,
  messages: []
};

function loadState() {
  try {
    const stored = JSON.parse(localStorage.getItem(cfg.storageKey) || '{}');
    state.conversationId = stored.conversationId || null;
    state.selectedDeviceId = stored.selectedDeviceId || null;
    state.selectedDeviceName = stored.selectedDeviceName || null;
    state.messages = Array.isArray(stored.messages) ? stored.messages.filter(m => m && String(m.content || '').trim()) : [];
  } catch (e) {
    state.conversationId = null;
    state.selectedDeviceId = null;
    state.selectedDeviceName = null;
    state.messages = [];
  }
}

function persist() {
  localStorage.setItem(cfg.storageKey, JSON.stringify({
    conversationId: state.conversationId,
    selectedDeviceId: state.selectedDeviceId,
    selectedDeviceName: state.selectedDeviceName,
    messages: state.messages.slice(-8)
  }));
}

function authHeader() {
  const token = localStorage.getItem('jwt_token');
  return token ? { 'X-Authorization': 'Bearer ' + token } : {};
}

function setBusy(busy) {
  state.busy = busy;
  sendEl.disabled = busy;
  inputEl.disabled = busy;
  sendEl.querySelector('.dg-chat__send-label').textContent = busy ? '…' : 'Send';
}

function clearThread() { messagesEl.innerHTML = ''; }

function deviceListHtml() {
  if (!devices.length) return '<div class="dg-chat__empty-text">No devices are available for your account.</div>';
  const items = devices.map((d, i) => '<li><strong>' + (i + 1) + '.</strong> ' + (d.name || 'device') + (d.type ? (' · ' + d.type) : '') + '</li>').join('');
  return '<ol class="dg-chat__device-list">' + items + '</ol>';
}

function showDevicePicker(intro) {
  clearThread();
  const empty = document.createElement('div');
  empty.className = 'dg-chat__empty';
  empty.innerHTML =
    '<div class="dg-chat__empty-title">Which device do you want to know about?</div>' +
    '<div class="dg-chat__empty-text">' + (intro || 'Reply with the device number or name from this list:') + '</div>' +
    deviceListHtml() +
    '<div class="dg-chat__empty-text" style="margin-top:10px">Example: <strong>1</strong> or <strong>DG SET1</strong></div>';
  messagesEl.appendChild(empty);
}

function appendMessage(role, text, meta) {
  const content = String(text || '').trim();
  if (!content) return;
  const empty = messagesEl.querySelector('.dg-chat__empty');
  if (empty) empty.remove();
  const row = document.createElement('div');
  row.className = 'dg-chat__row dg-chat__row--' + (role === 'USER' ? 'user' : 'assistant');
  const avatar = document.createElement('div');
  avatar.className = 'dg-chat__avatar';
  avatar.textContent = role === 'USER' ? 'OP' : 'AI';
  const bubble = document.createElement('div');
  bubble.className = 'dg-chat__bubble';
  bubble.textContent = content;
  if (meta) {
    const metaEl = document.createElement('div');
    metaEl.className = 'dg-chat__meta';
    metaEl.textContent = meta;
    bubble.appendChild(metaEl);
  }
  row.appendChild(avatar);
  row.appendChild(bubble);
  messagesEl.appendChild(row);
  messagesEl.scrollTop = messagesEl.scrollHeight;
}

function remember(role, content) {
  const text = String(content || '').trim();
  if (!text) return;
  state.messages.push({ role: role, content: text });
  if (state.messages.length > 8) state.messages = state.messages.slice(-8);
  persist();
}

function updateSelectedBanner() {
  let banner = root.querySelector('.dg-chat__selected');
  if (!state.selectedDeviceName) {
    if (banner) banner.remove();
    return;
  }
  if (!banner) {
    banner = document.createElement('div');
    banner.className = 'dg-chat__selected';
    root.insertBefore(banner, root.querySelector('.dg-chat__bottom'));
  }
  banner.innerHTML = 'Talking about <strong>' + state.selectedDeviceName + '</strong> · type <em>change device</em> to switch';
}

function matchDevice(text) {
  const raw = String(text || '').trim();
  if (!raw || !devices.length) return null;
  // number selection
  const num = raw.match(/^\\s*(\\d{1,2})\\s*[.)]?\\s*$/);
  if (num) {
    const idx = parseInt(num[1], 10) - 1;
    if (idx >= 0 && idx < devices.length) return devices[idx];
  }
  const lower = raw.toLowerCase();
  // exact / contains name
  let hit = devices.find(d => (d.name || '').toLowerCase() === lower);
  if (hit) return hit;
  hit = devices.find(d => (d.name || '').toLowerCase().includes(lower) || lower.includes((d.name || '').toLowerCase()));
  if (hit) return hit;
  // "use DG SET1" / "switch to gateway001"
  for (const d of devices) {
    const n = (d.name || '').toLowerCase();
    if (n && lower.includes(n)) return d;
  }
  return null;
}

function wantsDeviceChange(text) {
  const lower = String(text || '').toLowerCase();
  return /\\b(change device|switch device|another device|other device|list devices|show devices)\\b/.test(lower);
}

function hydrate() {
  if (!state.selectedDeviceId) {
    showDevicePicker();
    return;
  }
  updateSelectedBanner();
  if (!state.messages.length) {
    clearThread();
    appendMessage('ASSISTANT', 'Ask about ' + state.selectedDeviceName + ' status, alarms, trends, shifts, or guidance.');
    return;
  }
  clearThread();
  state.messages.forEach(msg => appendMessage(msg.role, msg.content));
}

async function loadDevices() {
  try {
    const res = await fetch(cfg.copilotBaseUrl + '/v1/devices', { headers: authHeader() });
    if (!res.ok) throw new Error('HTTP ' + res.status);
    devices = await res.json();
    // drop stale selected device if no longer accessible
    if (state.selectedDeviceId && !devices.some(d => d.id === state.selectedDeviceId)) {
      state.selectedDeviceId = null;
      state.selectedDeviceName = null;
      state.conversationId = null;
      state.messages = [];
      persist();
    }
    hydrate();
  } catch (err) {
    clearThread();
    appendMessage('ASSISTANT', 'Could not load devices from the assistant service. Please retry in a moment.', 'Error');
  }
}

async function askCopilot(text) {
  const payload = {
    message: text,
    conversationId: state.conversationId,
    messages: state.messages
  };
  if (state.selectedDeviceId) payload.deviceId = state.selectedDeviceId;
  const res = await fetch(cfg.copilotBaseUrl + '/v1/chat', {
    method: 'POST',
    headers: Object.assign({ 'Content-Type': 'application/json' }, authHeader()),
    body: JSON.stringify(payload)
  });
  if (!res.ok) throw new Error('HTTP ' + res.status);
  return res.json();
}

async function sendPrompt() {
  const text = (inputEl.value || '').trim();
  if (!text || state.busy) return;

  appendMessage('USER', text, new Date().toLocaleTimeString());
  remember('USER', text);
  inputEl.value = '';

  // Explicit change-device flow
  if (wantsDeviceChange(text) && !matchDevice(text)) {
    state.selectedDeviceId = null;
    state.selectedDeviceName = null;
    state.conversationId = null;
    state.messages = state.messages.slice(-2);
    persist();
    updateSelectedBanner();
    showDevicePicker('Sure — which device should I use now?');
    return;
  }

  // First-time / no device selected: treat message as device choice when possible
  if (!state.selectedDeviceId) {
    const chosen = matchDevice(text);
    if (chosen) {
      state.selectedDeviceId = chosen.id;
      state.selectedDeviceName = chosen.name;
      state.conversationId = null;
      persist();
      updateSelectedBanner();
      appendMessage('ASSISTANT', 'Okay — I will answer for ' + chosen.name + '. What would you like to know?');
      remember('ASSISTANT', 'Okay — I will answer for ' + chosen.name + '. What would you like to know?');
      return;
    }
    // Not a clear device pick: ask again with list, and also let backend clarify
  }

  // If user names another device mid-chat, switch
  const maybe = matchDevice(text);
  if (maybe && state.selectedDeviceId && maybe.id !== state.selectedDeviceId && /\\b(switch|change|use|about)\\b/i.test(text)) {
    state.selectedDeviceId = maybe.id;
    state.selectedDeviceName = maybe.name;
    state.conversationId = null;
    persist();
    updateSelectedBanner();
  }

  setBusy(true);
  try {
    const data = await askCopilot(text);
    state.conversationId = data.conversationId || state.conversationId;
    if (data.resolvedDevice && data.resolvedDevice.id) {
      state.selectedDeviceId = data.resolvedDevice.id;
      state.selectedDeviceName = data.resolvedDevice.name;
      updateSelectedBanner();
    }
    persist();
    let answer = data.answer || 'No answer returned.';
    // If backend asks to choose device, append local numbered list for convenience
    if (!state.selectedDeviceId || data.intent === 'clarify_device') {
      const names = devices.map((d, i) => (i + 1) + '. ' + d.name).join('\\n');
      if (names && answer.indexOf(devices[0] && devices[0].name) === -1) {
        answer = answer + '\\n\\nAvailable devices:\\n' + names;
      }
      showDevicePicker(answer);
      remember('ASSISTANT', answer);
    } else {
      appendMessage('ASSISTANT', answer, new Date(data.timestamp || Date.now()).toLocaleTimeString());
      remember('ASSISTANT', answer);
    }
  } catch (err) {
    appendMessage('ASSISTANT', 'Request failed: ' + err.message, 'Error');
  } finally {
    setBusy(false);
  }
}

sendEl.addEventListener('click', sendPrompt);
inputEl.addEventListener('keydown', e => {
  if (e.key === 'Enter' && !e.shiftKey) {
    e.preventDefault();
    sendPrompt();
  }
});
loadState();
loadDevices();
